// Generates src/renderer/src/locales/<lang>.json for the 21 UI languages.
//
// Translations are sourced from the Cobaltium Android app's res/values-*/strings.xml
// (authoritative, human-reviewed). Each desktop key maps to an Android string key
// where one exists; desktop-only strings fall back to their English text.
//
// Run: node scripts/gen-locales.mjs
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

