function unescapeAndroid(value) {
  return value
    .replace(/\\'/g, "'")
    .replace(/\\"/g, '"')
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, '\t')
    .replace(/\\\\/g, '\\')
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(parseInt(dec, 10)))
    .replace(/&amp;/g, '&')
}

function convertPlaceholders(value) {
  // Android %1$d / %1$s -> {1}; bare %d/%s -> {1}
  return value
    .replace(/%(\d+)\$[ds]/g, '{$1}')
    .replace(/%[ds]/g, '{1}')
}

function parseStringsFile(path) {
  const xml = readFileSync(path, 'utf8')
  const map = new Map()
  const re = /<string name="([^"]+)"[^>]*>([\s\S]*?)<\/string>/g
  let match
  while ((match = re.exec(xml)) !== null) {
    map.set(match[1], convertPlaceholders(unescapeAndroid(match[2]).replace(/\s+/g, ' ').trim()))
  }
  return map
}

