function main() {
  const stringsByLang = {}
  const englishByKey = {}
  for (const [code, dir] of Object.entries(LANGUAGES)) {
    const path = join(resRoot, dir, 'strings.xml')
    if (!existsSync(path)) {
      console.error(`Missing ${path}`)
      process.exit(1)
    }
    stringsByLang[code] = parseStringsFile(path)
  }

  const androidEnglish = stringsByLang.en

  mkdirSync(outDir, { recursive: true })
  let missing = 0
  let total = 0

  for (const [code] of Object.entries(LANGUAGES)) {
    const dict = {}
    for (const [key, androidKey, fallback] of ENTRIES) {
      total++
      let value = null
      if (androidKey) {
        const table = stringsByLang[code]
        value = table.get(androidKey) ?? null
        if (code !== 'en' && value == null) {
          // fall through to English
        }
      }
      if (value == null) value = fallback
      if (code !== 'en' && SUPPLEMENTAL[key] && SUPPLEMENTAL[key][code]) {
        value = SUPPLEMENTAL[key][code]
      }
      dict[key] = value
      if (
        code !== 'en' &&
        androidKey &&
        !stringsByLang[code].has(androidKey) &&
        !(SUPPLEMENTAL[key] && SUPPLEMENTAL[key][code])
      ) {
        missing++
      }
    }
    englishByKey[code] = dict
    writeFileSync(join(outDir, `${code}.json`), JSON.stringify(dict, null, 2) + '\n', 'utf8')
  }

  console.log(`Wrote ${Object.keys(LANGUAGES).length} locale files to ${outDir}`)
  console.log(`Entries: ${ENTRIES.length}; total values: ${total}; missing translations (English fallback): ${missing}`)
  void englishByKey
  void androidEnglish
}

main()
